mapper.select:
SELECT a.id, a.title, a.description, a.class_id, a.unit_id, a.created_by, a.deadline, a.weight, a.ideal_study_time_minutes, a.created_time, a.deleted, c.name as class_name, u.name as unit_name, creator.real_name as creator_name, creator.nickname as creator_nickname FROM assignments a LEFT JOIN classes c ON a.class_id = c.id AND c.deleted = 0 LEFT JOIN units u ON a.unit_id = u.id LEFT JOIN users creator ON a.created_by = creator.id AND creator.deleted = 0 WHERE a.deleted = 0
AND a.created_by = #{teacherId}
AND a.class_id = #{classId}
AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY a.created_time DESC
